SELECT 'signals.total' k, CAST(count(*) AS STRING) v FROM `/kestrel-01f4ab/Medication Safety Signal Monitor/Data/curated/ontology_signal_signals` UNION ALL SELECT 'signals.ranked', CAST(sum(CASE WHEN is_ranked THEN 1 ELSE 0 END) AS STRING) FROM `/kestrel-01f4ab/Medication Safety Signal Monitor/Data/curated/ontology_signal_signals` UNION ALL SELECT concat('signals.label_status.', label_status), CAST(count(*) AS STRING) FROM `/kestrel-01f4ab/Medication Safety Signal Monitor/Data/curated/ontology_signal_signals` GROUP BY label_status UNION ALL SELECT 'signals.drugs', CAST(count(DISTINCT ingredient_rxcui) AS STRING) FROM `/kestrel-01f4ab/Medication Safety Signal Monitor/Data/curated/ontology_signal_signals` UNION ALL SELECT 'signals.naion_rank', CAST(max(rank_in_bucket) AS STRING) FROM `/kestrel-01f4ab/Medication Safety Signal Monitor/Data/curated/ontology_signal_signals` WHERE pt = 'Optic ischaemic neuropathy' AND ingredient_name = 'semaglutide' UNION ALL SELECT 'signals.naion_a', CAST(max(a_drug_reaction) AS STRING) FROM `/kestrel-01f4ab/Medication Safety Signal Monitor/Data/curated/ontology_signal_signals` WHERE pt = 'Optic ischaemic neuropathy' AND ingredient_name = 'semaglutide' UNION ALL SELECT 'signals.naion_prr', CAST(round(max(prr),1) AS STRING) FROM `/kestrel-01f4ab/Medication Safety Signal Monitor/Data/curated/ontology_signal_signals` WHERE pt = 'Optic ischaemic neuropathy' AND ingredient_name = 'semaglutide' UNION ALL SELECT 'ae_stats.total', CAST(count(*) AS STRING) FROM `/kestrel-01f4ab/Medication Safety Signal Monitor/Data/curated/ontology_ae_stats` UNION ALL SELECT 'faers.cases_current', CAST(count(*) AS STRING) FROM `/kestrel-01f4ab/Medication Safety Signal Monitor/Data/clean/clean_faers_cases_current` UNION ALL SELECT 'faers.case_reactions', CAST(count(*) AS STRING) FROM `/kestrel-01f4ab/Medication Safety Signal Monitor/Data/clean/clean_faers_case_reactions` UNION ALL SELECT 'faers.drug_reaction_rows', CAST(count(*) AS STRING) FROM `/kestrel-01f4ab/Medication Safety Signal Monitor/Data/clean/clean_faers_drug_reaction` UNION ALL SELECT 'recalls.total', CAST(count(*) AS STRING) FROM `/kestrel-01f4ab/Medication Safety Signal Monitor/Data/curated/ontology_recall_recalls` UNION ALL SELECT 'recalls.active', CAST(sum(CASE WHEN is_active THEN 1 ELSE 0 END) AS STRING) FROM `/kestrel-01f4ab/Medication Safety Signal Monitor/Data/curated/ontology_recall_recalls` UNION ALL SELECT 'labels.total', CAST(count(*) AS STRING) FROM `/kestrel-01f4ab/Medication Safety Signal Monitor/Data/curated/ontology_label_labels` UNION ALL SELECT concat('changes.', found_by), CAST(count(*) AS STRING) FROM `/kestrel-01f4ab/Medication Safety Signal Monitor/Data/curated/ontology_change_events` GROUP BY found_by UNION ALL SELECT 'changes.total', CAST(count(*) AS STRING) FROM `/kestrel-01f4ab/Medication Safety Signal Monitor/Data/curated/ontology_change_events` UNION ALL SELECT 'ai.sections', CAST(count(*) AS STRING) FROM `/kestrel-01f4ab/Medication Safety Signal Monitor/Data/curated/ai_label_section_extractions` UNION ALL SELECT 'ai.from_cache', CAST(sum(CASE WHEN from_cache THEN 1 ELSE 0 END) AS STRING) FROM `/kestrel-01f4ab/Medication Safety Signal Monitor/Data/curated/ai_label_section_extractions` UNION ALL SELECT 'ai.reactions', CAST(sum(n_reactions) AS STRING) FROM `/kestrel-01f4ab/Medication Safety Signal Monitor/Data/curated/ai_label_section_extractions` UNION ALL SELECT 'ai.grounded', CAST(sum(n_grounded) AS STRING) FROM `/kestrel-01f4ab/Medication Safety Signal Monitor/Data/curated/ai_label_section_extractions` UNION ALL SELECT 'monitoring.runs', CAST(count(DISTINCT run_at) AS STRING) FROM `/kestrel-01f4ab/Medication Safety Signal Monitor/Data/monitoring/monitoring_checks` UNION ALL SELECT concat('monitoring.last.', check_id), concat(CAST(round(value,4) AS STRING), ' ', status) FROM `/kestrel-01f4ab/Medication Safety Signal Monitor/Data/monitoring/monitoring_checks` WHERE run_at = (SELECT max(run_at) FROM `/kestrel-01f4ab/Medication Safety Signal Monitor/Data/monitoring/monitoring_checks`) 